-- ============================================================================
-- A12 - COMPLETE LOAD
-- EWM (Storage Bins + Handling Units SSCC-17 + Warehouse Tasks)
-- Colocacao de estoque amarrada as decisoes de UD do A10:
--   APPROVED -> bin UNR (estoque livre)  |  PENDING -> bin QI (bloqueado p/ inspecao)  |  REJECTED -> bin BLK (bloqueado)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.WAREHOUSE_TASK CASCADE;
DROP TABLE INDUSTRIAL_DATA.HANDLING_UNIT CASCADE;
DROP TABLE INDUSTRIAL_DATA.STORAGE_BIN CASCADE;
DROP TABLE INDUSTRIAL_DATA.STORAGE_TYPE CASCADE;
DROP TABLE INDUSTRIAL_DATA.WAREHOUSE_NUMBER CASCADE;

-- FASE 2: CREATE CONFIG TABLES
CREATE TABLE INDUSTRIAL_DATA.WAREHOUSE_NUMBER (WAREHOUSE_ID NVARCHAR(4) NOT NULL PRIMARY KEY, WAREHOUSE_TEXT NVARCHAR(60) NOT NULL);
CREATE TABLE INDUSTRIAL_DATA.STORAGE_TYPE (STORAGE_TYPE_CODE NVARCHAR(4) NOT NULL PRIMARY KEY, STORAGE_TYPE_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA


-- FASE 4: CREATE STORAGE BIN
CREATE TABLE INDUSTRIAL_DATA.STORAGE_BIN (
  BIN_ID NVARCHAR(15) NOT NULL PRIMARY KEY,
  WAREHOUSE_ID NVARCHAR(4) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  STORAGE_TYPE_CODE NVARCHAR(4) NOT NULL,
  AISLE NVARCHAR(4) NOT NULL,
  BIN_LEVEL NVARCHAR(4) NOT NULL,
  FOREIGN KEY (WAREHOUSE_ID) REFERENCES INDUSTRIAL_DATA.WAREHOUSE_NUMBER(WAREHOUSE_ID),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (STORAGE_TYPE_CODE) REFERENCES INDUSTRIAL_DATA.STORAGE_TYPE(STORAGE_TYPE_CODE)
);

-- FASE 5: CREATE HANDLING UNIT (SSCC-17) + WAREHOUSE TASK
CREATE TABLE INDUSTRIAL_DATA.HANDLING_UNIT (
  HU_ID NVARCHAR(17) NOT NULL PRIMARY KEY,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  LOT_ID NVARCHAR(12) NOT NULL,
  QUANTITY DECIMAL(15, 2) NOT NULL,
  CREATED_DATE DATE NOT NULL,
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (LOT_ID) REFERENCES INDUSTRIAL_DATA.INSPECTION_LOT(LOT_ID),
  CHECK (QUANTITY >= 0)
);

CREATE TABLE INDUSTRIAL_DATA.WAREHOUSE_TASK (
  TASK_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  HU_ID NVARCHAR(17) NOT NULL,
  SOURCE_BIN_ID NVARCHAR(15) NOT NULL,
  DEST_BIN_ID NVARCHAR(15) NOT NULL,
  TASK_STATUS NVARCHAR(10) NOT NULL,
  TASK_DATE DATE NOT NULL,
  FOREIGN KEY (HU_ID) REFERENCES INDUSTRIAL_DATA.HANDLING_UNIT(HU_ID),
  FOREIGN KEY (SOURCE_BIN_ID) REFERENCES INDUSTRIAL_DATA.STORAGE_BIN(BIN_ID),
  FOREIGN KEY (DEST_BIN_ID) REFERENCES INDUSTRIAL_DATA.STORAGE_BIN(BIN_ID)
);

-- FASE 6: LOAD STORAGE BINS (100 posicoes: 1 GR + 2 UNR + 1 QI + 1 BLK por planta)

-- FASE 7: LOAD HANDLING UNITS (116 HUs, 1 por lote de inspecao do A10)

-- FASE 8: LOAD WAREHOUSE TASKS (116 movimentacoes: GR staging -> bin final conforme UD)

-- FASE 9: VALIDACAO FINAL
SELECT 'A12 LOADED SUCCESSFULLY' FROM DUMMY;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.WAREHOUSE_NUMBER;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.STORAGE_TYPE;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.STORAGE_BIN;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.HANDLING_UNIT;
SELECT COUNT(*) FROM INDUSTRIAL_DATA.WAREHOUSE_TASK;
SELECT SB.STORAGE_TYPE_CODE, COUNT(*) FROM INDUSTRIAL_DATA.WAREHOUSE_TASK WT JOIN INDUSTRIAL_DATA.STORAGE_BIN SB ON WT.DEST_BIN_ID = SB.BIN_ID GROUP BY SB.STORAGE_TYPE_CODE ORDER BY SB.STORAGE_TYPE_CODE;
SELECT TOP 5 HU_ID, MATNR, WERKS, LOT_ID, QUANTITY FROM INDUSTRIAL_DATA.HANDLING_UNIT ORDER BY HU_ID;
